"""stablehand lint: static checks for agent artifacts.

Checks skills (SKILL.md folders), agents/subagents, rules and instruction files
against the formats accepted by Claude Code, Antigravity and OpenCode, and finds
cross-platform collisions in a project.

Usage:
  uv run lint.py --platform claude-code PATH [PATH ...]
  uv run lint.py --project DIR [--platform P ...]
  uv run lint.py --cards DIR        platform cards: is "Last verified" recent?
Options:
  --json     machine-readable output
  --strict   exit 1 on warnings as well as errors

A PATH can be a skill folder, a SKILL.md, an agent file, a rule file, an
instruction file (AGENTS.md / CLAUDE.md / GEMINI.md) or a plugin/folder root that
contains skills/ and agents/.

Suppress a finding for one file with an HTML comment anywhere in it:
  <!-- stablehand-lint: ignore S024, A013 -->

Exit codes: 0 clean, 1 findings at the failing level, 2 usage error.
"""

from __future__ import annotations

import argparse
import json
import os
import posixpath
import re
import sys
from dataclasses import asdict, dataclass, field
from datetime import date
from pathlib import Path
from urllib.parse import unquote

try:
    import yaml
except ImportError:  # pragma: no cover
    sys.exit("stablehand lint needs PyYAML. Run it with `uv run lint.py ...` (installs it automatically).")

PLATFORMS = ("claude-code", "antigravity", "opencode")
LEVELS = ("error", "warning", "info")

NAME_RE = re.compile(r"^[a-z0-9]+(-[a-z0-9]+)*$")
IGNORE_RE = re.compile(r"<!--\s*stablehand-lint:\s*ignore\s+([A-Z0-9,\s]+?)\s*-->")
MD_LINK_RE = re.compile(r"\[[^\]]*\]\(([^)\s]+)\)")
BUNDLED_PATH_RE = re.compile(r"`((?:references|scripts|assets|examples|resources)/[^`\s]+)`")
PLUGIN_PATH_RE = re.compile(r"\$\{CLAUDE_PLUGIN_ROOT\}/([^\s`\"')\]]+)")
FENCE_RE = re.compile(r"^[ \t]*(`{3,}|~{3,}).*?(?:^[ \t]*\1[ \t]*$|\Z)", re.M | re.S)
CLAUDE_SUBST_RE = re.compile(r"\$ARGUMENTS|\$\{CLAUDE_[A-Z_]+\}|!`")
CLAUDE_TOOL_TEXT_RE = re.compile(
    r"\b(AskUserQuestion|TodoWrite|NotebookEdit|WebFetch|WebSearch|MultiEdit|subagent_type)\b"
    r"|\b(Agent|Skill|Task|Read|Grep|Glob|Bash|Edit|Write) tool\b"
)
AG_TOOL_TEXT_RE = re.compile(
    r"\b(view_file|view_file_outline|view_code_item|replace_file_content|multi_replace_file_content|"
    r"write_to_file|grep_search|find_by_name|list_dir|codebase_search|run_command|invoke_subagent|"
    r"define_subagent|search_web|read_url_content)\b"
)

