@dataclass
class Finding:
    level: str
    code: str
    path: str
    message: str


@dataclass
class Report:
    findings: list[Finding] = field(default_factory=list)
    files_checked: int = 0

    def add(self, level: str, code: str, path: Path | str, message: str) -> None:
        self.findings.append(Finding(level, code, str(path), message))

    def count(self, level: str) -> int:
        return sum(1 for f in self.findings if f.level == level)


@dataclass
class Doc:
    path: Path
    text: str
    frontmatter: dict | None
    raw_frontmatter: str | None
    body: str
    error: str | None
    ignored: set[str]


def one_of(value, allowed: set[str]) -> bool:
    """Membership that never crashes on unhashable YAML values (lists, mappings)."""
    return isinstance(value, str) and value in allowed


def is_link(path: Path) -> bool:
    return os.path.islink(path) or bool(getattr(os.path, "isjunction", lambda _: False)(path))


def walk_files(root: Path) -> list[Path]:
    """Files under root without entering symlinks or junctions (they can loop)."""
    found: list[Path] = []
    for entry in sorted(os.scandir(root), key=lambda e: e.name):
        path = Path(entry.path)
        if is_link(path):
            continue
        if entry.is_dir():
            found += walk_files(path)
        elif entry.is_file():
            found.append(path)
    return found


def read_doc(path: Path) -> Doc:
    raw = path.read_text(encoding="utf-8-sig", errors="replace")
    text = raw.replace("\r\n", "\n")
    ignored = {c.strip() for m in IGNORE_RE.finditer(text) for c in m.group(1).split(",") if c.strip()}
    if not text.startswith("---\n"):
        return Doc(path, text, None, None, text, None, ignored)
    end = text.find("\n---", 3)
    if end == -1:
        return Doc(path, text, None, None, text, "frontmatter opened with --- but never closed", ignored)
    raw_fm = text[4:end] if end >= 4 else ""
    body = text[end + 4:].lstrip("\n")
    try:
        data = yaml.safe_load(raw_fm) if raw_fm.strip() else {}
    except yaml.YAMLError as exc:
        hint = " (an unquoted value containing ': ' is the usual cause; wrap it in double quotes)"
        return Doc(path, text, None, raw_fm, body, f"invalid YAML: {str(exc).splitlines()[0]}{hint}", ignored)
    if not isinstance(data, dict):
        return Doc(path, text, None, raw_fm, body, "frontmatter is not a YAML mapping", ignored)
    return Doc(path, text, data, raw_fm, body, None, ignored)


class Scoped:
    """Adds findings for one file, honouring that file's ignore comment."""

    def __init__(self, report: Report, path: Path, ignored: set[str]):
        self.report, self.path, self.ignored = report, path, ignored

    def __call__(self, level: str, code: str, message: str) -> None:
        if code not in self.ignored:
            self.report.add(level, code, self.path, message)


def unquoted_with_colon(raw_fm: str | None, key: str) -> bool:
    if not raw_fm:
        return False
    m = re.search(rf"^{re.escape(key)}:[ \t]*(.*)$", raw_fm, re.MULTILINE)
    if not m:
        return False
    value = m.group(1).strip()
    return bool(value) and value[0] not in "\"'>|" and ": " in value


def check_foreign_text(add: Scoped, text: str, platform: str) -> None:
    if platform != "claude-code":
        if m := CLAUDE_TOOL_TEXT_RE.search(text):
            add("warning", "S024", f"mentions Claude Code tool '{m.group(0)}'; describe the action or use this platform's mechanism")
        if m := CLAUDE_SUBST_RE.search(text):
            add("warning", "S025", f"uses Claude-only substitution '{m.group(0)}'")
    if platform != "antigravity" and (m := AG_TOOL_TEXT_RE.search(text)):
        add("warning", "S024", f"mentions Antigravity tool '{m.group(0)}'")


# --- skills ----------------------------------------------------------------------
def lint_skill(report: Report, skill_dir: Path, platform: str) -> None:
    skill_md = skill_dir / "SKILL.md"
    if not skill_md.is_file():
        report.add("error", "S001", skill_dir, "skill folder has no SKILL.md")
        return
    report.files_checked += 1
    doc = read_doc(skill_md)
    add = Scoped(report, skill_md, doc.ignored)
    if doc.error:
        add("error", "S002", doc.error)
        return
    fm = doc.frontmatter
    if fm is None:
        add("error", "S002", "missing YAML frontmatter (--- name/description ---)")
        return

    name = fm.get("name")
    if name is None:
        if platform != "opencode":
            add("warning", "S003", f"no name: {platform} defaults to the folder name, OpenCode requires it")
        else:
            add("error", "S003", "name is required")
    elif not isinstance(name, str):
        add("error", "S004", "name must be a string")
    else:
        if not NAME_RE.match(name) or len(name) > 64:
            add("error", "S004", f"name '{name}' must be lowercase letters/digits/single hyphens, at most 64 chars")
        if name != skill_dir.name:
            add("error", "S005", f"name '{name}' does not match folder '{skill_dir.name}'")

    desc = fm.get("description")
    if desc is None or (isinstance(desc, str) and not desc.strip()):
        add("error", "S006", "description is required")
    elif not isinstance(desc, str):
        add("error", "S006", "description must be a string")
    else:
        if len(desc) > 1024:
            add("error", "S007", f"description is {len(desc)} chars (max 1024)")
        elif len(desc) > 500:
            add("info", "S008", f"description is {len(desc)} chars; aim for <= 500 so routing stays sharp")
        if "<" in desc or ">" in desc:
            add("warning", "S009", "description contains '<' or '>' (rejected by some loaders)")
        if platform == "claude-code":
            combined = len(desc) + len(str(fm.get("when_to_use") or ""))
            if combined > CLAUDE_DESCRIPTION_LISTING_CAP:
                add("warning", "S011", f"description + when_to_use = {combined} chars; the listing truncates at {CLAUDE_DESCRIPTION_LISTING_CAP}")
    if unquoted_with_colon(doc.raw_frontmatter, "description"):
        add("warning" if platform == "antigravity" else "info", "S010",
            "description contains ': ' but is not quoted (broke Antigravity CLI < 1.3.6); wrap it in double quotes")

    for key in sorted(set(fm) - SKILL_KEYS[platform], key=str):
        add("warning", "S012", f"frontmatter key '{key}' is not used by {platform}")

    meta = fm.get("metadata")
    if meta is not None:
        if not isinstance(meta, dict):
            add("error", "S013", "metadata must be a mapping of string keys to string values")
        else:
            for k, v in meta.items():
                if not isinstance(v, str):
                    add("warning", "S013", f"metadata.{k} should be a string (quote it)")
            if platform == "opencode":
                for k in ("opencode/slash", "opencode/autoinvoke"):
                    if k in meta and meta[k] not in ("true", "false"):
                        add("error", "S014", f"metadata.{k} must be the string \"true\" or \"false\"")

    if platform == "claude-code":
        for key in ("disable-model-invocation", "user-invocable", "background"):
            if key in fm and not isinstance(fm[key], bool):
                add("warning", "S015", f"{key} should be true or false")
        if "context" in fm and fm["context"] != "fork":
            add("error", "S015", "context only accepts 'fork'")
        if "effort" in fm and not one_of(fm["effort"], EFFORTS):
            add("warning", "S015", f"effort should be one of {sorted(EFFORTS)}")
    if platform == "antigravity":
        for key in ("disable-slash-command", "disable-model-invocation"):
            if key in fm and not isinstance(fm[key], bool):
                add("warning", "S015", f"{key} should be true or false")

    body_lines = doc.body.count("\n") + 1
    if not doc.body.strip():
        add("error", "S018", "SKILL.md has no body")
    if body_lines > 500:
        add("warning", "S016", f"SKILL.md body is {body_lines} lines (aim for < 500; move detail to references/)")
    body_bytes = len(doc.body.encode("utf-8"))
    if body_bytes > AG_FILE_BYTES:
        add("warning" if platform == "antigravity" else "info", "S017", f"body is {body_bytes} bytes (Antigravity warns above 24 KB)")

    check_skill_files(add, skill_dir, doc.text)
    check_plugin_paths(add, skill_dir, doc.text)
    check_foreign_text(add, doc.body, platform)


def strip_fences(text: str) -> str:
    return FENCE_RE.sub("", text)


def check_skill_files(add: Scoped, skill_dir: Path, text: str) -> None:
    prose = strip_fences(text)
    targets = [m.group(1) for m in MD_LINK_RE.finditer(prose)] + [m.group(1) for m in BUNDLED_PATH_RE.finditer(prose)]
    for target in targets:
        target = unquote(target)
        if re.match(r"^[a-z]+:", target) or target.startswith(("#", "/", "~")) or any(c in target for c in "$<>*"):
            continue  # URLs, anchors, absolute paths, variables, placeholders and globs
        rel = target.split("#", 1)[0]
        if not rel:
            continue
        rel = posixpath.normpath(rel)
        if rel.startswith(".."):
            add("warning", "S021", f"link '{rel}' leaves the skill folder; it breaks when the skill is installed on its own")
            continue
        if not (skill_dir / rel).exists():
            add("error", "S020", f"referenced file not found: {rel}")
    refs_dir = skill_dir / "references"
    if refs_dir.is_dir() and not is_link(refs_dir):
        for f in walk_files(refs_dir):
            rel = f.relative_to(skill_dir).as_posix()
            if rel not in text and f.name not in text:
                add("warning", "S022", f"{rel} is never referenced from SKILL.md (orphan)")
    for nested in walk_files(skill_dir):
        if nested.name == "SKILL.md" and nested.parent != skill_dir:
            add("warning", "S023", f"nested skill {nested.relative_to(skill_dir).as_posix()} is not discovered by most harnesses")


def plugin_root(path: Path) -> Path | None:
    return next((p for p in path.resolve().parents if (p / ".claude-plugin").is_dir()), None)


def check_plugin_paths(add: Scoped, skill_dir: Path, text: str) -> None:
    """${CLAUDE_PLUGIN_ROOT}/... paths resolve against the nearest folder holding .claude-plugin/."""
    root = plugin_root(skill_dir / "SKILL.md")
    if root is None:
        return
    for m in PLUGIN_PATH_RE.finditer(strip_fences(text)):
        rel = unquote(m.group(1)).split("#", 1)[0].rstrip(".,;:")
        if rel and not any(c in rel for c in "$<>*") and not (root / rel).exists():
            add("error", "S020", f"referenced file not found: ${{CLAUDE_PLUGIN_ROOT}}/{rel}")


# --- agents ----------------------------------------------------------------------
def lint_agent(report: Report, path: Path, platform: str) -> None:
    report.files_checked += 1
    doc = read_doc(path)
    add = Scoped(report, path, doc.ignored)
    if doc.error:
        add("error", "A001", doc.error)
        return
    fm = doc.frontmatter
    if fm is None:
        add("error", "A001", "missing YAML frontmatter")
        return
    if not doc.body.strip():
        add("error", "A002", "agent has no body (system prompt)")
    elif doc.body.count("\n") + 1 > 300:
        add("warning", "A003", "agent prompt is over 300 lines; move knowledge into skills and preload them")
    {"claude-code": lint_claude_agent, "antigravity": lint_antigravity_agent, "opencode": lint_opencode_agent}[platform](add, path, fm, doc)
    check_foreign_text(add, doc.body, platform)


def as_list(value) -> list[str]:
    if isinstance(value, str):
        return [p.strip() for p in re.split(r",(?![^(]*\))", value) if p.strip()]
    if isinstance(value, list):
        return [str(v).strip() for v in value]
    return []


def lint_claude_agent(add: Scoped, path: Path, fm: dict, doc: Doc) -> None:
    name = fm.get("name")
    if not isinstance(name, str) or not name:
        add("error", "A010", "name is required")
    else:
        if ":" in name or name.startswith("-") or len(name) > 256:
            add("error", "A010", "name must not contain ':' or start with '-', and is at most 256 chars")
        elif not NAME_RE.match(name):
            add("info", "A010", f"name '{name}' is not kebab-case")
    if not isinstance(fm.get("description"), str) or not fm["description"].strip():
        add("error", "A011", "description is required (it is the delegation trigger)")
    for key in sorted(set(fm) - CLAUDE_AGENT_KEYS, key=str):
        add("warning", "A012", f"frontmatter key '{key}' is not a Claude Code agent field (ignored)")
    for key in ("tools", "disallowedTools"):
        for tool in as_list(fm.get(key)):
            base = tool.split("(", 1)[0]
            if not (tool.startswith("mcp__") or base in CLAUDE_TOOLS):
                add("warning", "A013", f"{key}: unknown tool '{tool}'")
            elif "(" in tool and not tool.startswith("mcp__"):
                effect = ("does not restrict commands" if key == "tools"
                          else "removes the whole tool, not only matching commands")
                add("warning", "A021", f"{key}: '{tool}' {effect}; restrict commands with a frontmatter PreToolUse hook")
    model = fm.get("model")
    if model is not None:
        model = str(model)
        if model.startswith("claude-"):
            add("info", "A014", "pins a full model ID; prefer a tier alias (DeepSeek and other compatible endpoints remap claude-* names)")
        elif model not in CLAUDE_MODEL_ALIASES:
            add("warning", "A015", f"model '{model}' is not an alias or claude-* ID; compatible endpoints reject unknown names")
    mode = fm.get("permissionMode")
    if mode is not None:
        if not one_of(mode, CLAUDE_PERMISSION_MODES):
            add("error", "A016", f"permissionMode must be one of {sorted(CLAUDE_PERMISSION_MODES)}")
        elif mode == "bypassPermissions":
            add("warning", "A017", "permissionMode bypassPermissions removes every safety prompt")
    if "color" in fm and not one_of(fm["color"], CLAUDE_COLORS):
        add("warning", "A018", f"color must be one of {sorted(CLAUDE_COLORS)}")
    if "effort" in fm and not one_of(fm["effort"], EFFORTS):
        add("warning", "A018", f"effort must be one of {sorted(EFFORTS)}")
    if "memory" in fm and not one_of(fm["memory"], CLAUDE_MEMORY):
        add("error", "A018", f"memory must be one of {sorted(CLAUDE_MEMORY)}")
    if "isolation" in fm and fm["isolation"] != "worktree":
        add("error", "A018", "isolation only accepts 'worktree'")
    if "maxTurns" in fm and not (isinstance(fm["maxTurns"], int) and fm["maxTurns"] > 0):
        add("error", "A018", "maxTurns must be a positive integer")
    if "background" in fm and not isinstance(fm["background"], bool):
        add("error", "A018", "background must be true or false")
    if "autoCompactWindow" in fm and not (isinstance(fm["autoCompactWindow"], int) and 100_000 <= fm["autoCompactWindow"] <= 1_000_000):
        add("error", "A018", "autoCompactWindow must be an integer from 100000 to 1000000")
    if len(as_list(fm.get("skills"))) > 32:
        add("warning", "A019", "more than 32 preloaded skills (Claude Code caps preloading at 32)")
    if in_claude_plugin(path):
        for key in ("hooks", "mcpServers", "permissionMode"):
            if key in fm:
                add("warning", "A020", f"'{key}' is ignored for plugin agents (use hooks/hooks.json or .mcp.json)")


def in_claude_plugin(path: Path) -> bool:
    return any((parent / ".claude-plugin").is_dir() for parent in path.resolve().parents)


def lint_antigravity_agent(add: Scoped, path: Path, fm: dict, doc: Doc) -> None:
    for key in ("name", "description"):
        if not isinstance(fm.get(key), str) or not fm[key].strip():
            add("error", "A030", f"{key} is required")
    for key in sorted(set(fm) - AG_AGENT_KEYS, key=str):
        add("warning", "A030", f"frontmatter key '{key}' is not an Antigravity agent field")
    if "tools" in fm:
        if not isinstance(fm["tools"], list):
            add("error", "A030", "tools must be a YAML list of tool names")
        else:
            for tool in fm["tools"]:
                if not isinstance(tool, str):
                    add("error", "A031", f"tools entry {tool!r} must be a tool name")
                elif tool in AG_TOOL_ALIASES:
                    add("error", "A031", f"unknown tool '{tool}' (model-facing alias; use canonical '{AG_TOOL_ALIASES[tool]}' in agent frontmatter — an unknown name can hang the subagent)")
                elif tool in AG_TOOLS_OBSERVED:
                    add("info", "A032", f"tool '{tool}' is observed in the product but not documented; verify it")
                elif tool not in AG_TOOLS_DOCUMENTED:
                    add("error", "A031", f"unknown tool '{tool}' (an unknown tool name can hang the subagent)")
    if "model" in fm and not one_of(fm["model"], AG_MODELS):
        add("error", "A033", f"model must be one of {sorted(AG_MODELS)}")
    if "commandExecutionPolicy" in fm and not one_of(fm["commandExecutionPolicy"], AG_EXEC_POLICIES):
        add("error", "A034", f"commandExecutionPolicy must be one of {sorted(AG_EXEC_POLICIES)}")
    for key in AG_AGENT_BOOLS:
        if key in fm and not isinstance(fm[key], bool):
            add("error", "A035", f"{key} must be true or false")
    for key in ("skills", "plugins", "rules", "agents"):
        if key in fm and not (isinstance(fm[key], list) and all(isinstance(v, str) for v in fm[key])):
            add("error", "A036", f"{key} must be a list of paths")
    if unquoted_with_colon(doc.raw_frontmatter, "description"):
        add("warning", "S010", "description contains ': ' but is not quoted; wrap it in double quotes")


def lint_opencode_agent(add: Scoped, path: Path, fm: dict, doc: Doc) -> None:
    if not isinstance(fm.get("description"), str) or not fm["description"].strip():
        add("error", "A040", "description is required")
    if "name" in fm:
        add("warning", "A041", "OpenCode takes the agent name from the file name; remove 'name'")
    if not NAME_RE.match(path.stem):
        add("warning", "A041", f"file name '{path.stem}' should be kebab-case (it is the agent name)")
    mode = fm.get("mode")
    if mode is None:
        add("info", "A042", "no mode: defaults to 'all' (primary and subagent)")
    elif not one_of(mode, OC_MODES):
        add("error", "A042", f"mode must be one of {sorted(OC_MODES)}")
    if "model" in fm and "/" not in str(fm["model"]):
        add("error", "A043", f"model '{fm['model']}' must be provider/model-id (e.g. deepseek/deepseek-flash)")
    if "tools" in fm:
        add("warning", "A044", "tools is deprecated in OpenCode; express access with permission")
        tools = fm["tools"]
        claude_tools = sorted({t for t in (tools if isinstance(tools, dict) else as_list(tools)) if one_of(t, CLAUDE_TOOLS)})
        if claude_tools:
            add("warning", "A044", f"tools uses Claude Code tool names {claude_tools}; OpenCode does not know them")
    if "maxSteps" in fm:
        add("warning", "A044", "maxSteps is deprecated; use steps")
    if "steps" in fm and not (isinstance(fm["steps"], int) and fm["steps"] > 0):
        add("error", "A045", "steps must be a positive integer")
    if "temperature" in fm and not (isinstance(fm["temperature"], (int, float)) and 0 <= fm["temperature"] <= 2):
        add("warning", "A045", "temperature should be a number between 0 and 2")
    if "hidden" in fm and mode != "subagent":
        add("warning", "A045", "hidden only applies to mode: subagent")
    if "color" in fm:
        color = str(fm["color"])
        if color not in OC_THEME_COLORS and not re.fullmatch(r"#[0-9a-fA-F]{6}", color):
            add("warning", "A045", "color must be a hex value or a theme color (primary, secondary, accent, success, warning, error, info)")
    perm = fm.get("permission")
    if perm is not None:
        if not isinstance(perm, dict):
            add("error", "A046", "permission must be a mapping")
        else:
            for key, value in perm.items():
                if key not in OC_PERMISSION_KEYS:
                    add("warning", "A046", f"permission key '{key}' is not a known OpenCode permission")
                values = value.values() if isinstance(value, dict) else [value]
                if not all(one_of(v, OC_PERMISSION_VALUES) for v in values):
                    add("error", "A047", f"permission.{key} values must be allow, ask or deny")
            if "shell" in perm and "bash" not in perm:
                add("error", "A049", "OpenCode 1.19 enforces only 'bash'; a 'shell' rule alone is ignored. Add 'bash' with the same rules")
            elif "bash" in perm and "shell" not in perm:
                add("warning", "A049", "current OpenCode docs name the key 'shell'; add 'shell' with the same rules as 'bash'")
            elif "bash" in perm and perm.get("bash") != perm.get("shell"):
                add("warning", "A049", "'bash' and 'shell' should carry identical rules")
    for key in sorted(set(fm) - OC_AGENT_KEYS, key=str):
        if key in OC_CLAUDE_ONLY_KEYS:
            add("warning", "A048", f"key '{key}' is Claude Code only; OpenCode ignores it and passes it to the model provider")
        else:
            add("info", "A048", f"key '{key}' is passed to the model provider as an option")


# --- rules and instructions --------------------------------------------------------
def lint_rule(report: Report, path: Path, platform: str) -> None:
    report.files_checked += 1
    doc = read_doc(path)
    add = Scoped(report, path, doc.ignored)
    if doc.error:
        add("error", "R001", doc.error)
        return
    fm = doc.frontmatter or {}
    if platform == "antigravity":
        trigger = fm.get("trigger")
        if not one_of(trigger, AG_TRIGGERS):
            add("error", "R001", f"trigger must be one of {sorted(AG_TRIGGERS)} (invalid rules are discarded silently)")
        if trigger == "model_decision" and not fm.get("description"):
            add("error", "R002", "trigger model_decision needs a description")
        if trigger == "glob" and not (fm.get("globs") or fm.get("glob")):
            add("error", "R003", "trigger glob needs globs")
        size = len(doc.text.encode("utf-8"))
        if size > AG_FILE_BYTES:
            add("error", "R004", f"rule is {size} bytes (Antigravity limit 24 KB)")
    elif platform == "claude-code":
        paths = fm.get("paths")
        if paths is not None and not (isinstance(paths, list) and all(isinstance(p, str) for p in paths)):
            add("error", "R005", "paths must be a list of glob strings")


def lint_instructions(report: Report, path: Path, platform: str) -> None:
    report.files_checked += 1
    doc = read_doc(path)
    add = Scoped(report, path, doc.ignored)
    lines = doc.text.count("\n") + 1
    if lines > 200:
        add("warning", "I001", f"{path.name} is {lines} lines; always-loaded files should stay under ~150")
    size = len(doc.text.encode("utf-8"))
    if size > AG_FILE_BYTES:
        add("warning", "I002", f"{path.name} is {size} bytes (Antigravity rule files are limited to 24 KB)")
    if path.name in ("AGENTS.md", "GEMINI.md") and doc.text.startswith("---\n"):
        add("warning", "I003", f"{path.name} takes no frontmatter")
    if path.name == "CLAUDE.md":
        agents_md = path.parent / "AGENTS.md"
        if not agents_md.exists() and path.parent.name == ".claude":
            agents_md = path.parent.parent / "AGENTS.md"
        if agents_md.exists() and "@AGENTS.md" not in doc.text:
            add("warning", "I004", "AGENTS.md exists but CLAUDE.md does not import it; Claude Code then ignores AGENTS.md (add '@AGENTS.md')")


# --- dispatch --------------------------------------------------------------------
INSTRUCTION_FILES = {"AGENTS.md", "CLAUDE.md", "GEMINI.md", "CLAUDE.local.md"}


def lint_container(report: Report, root: Path, platform: str) -> None:
    skills = root / "skills"
    if skills.is_dir():
        for d in sorted(p for p in skills.iterdir() if p.is_dir()):
            lint_skill(report, d, platform)
    agents = root / "agents"
    if agents.is_dir():
        for f in agent_files(agents, platform):
            lint_agent(report, f, platform)
    rules = root / "rules"
    if rules.is_dir():
        for f in sorted(rules.glob("*.md")):
            lint_rule(report, f, platform)
    if platform == "antigravity":
        manifest = root / ".antigravity-plugin" / "plugin.json"
        if not manifest.is_file():
            manifest = root / "plugin.json"
        if manifest.is_file():
            lint_antigravity_manifest(report, manifest)


def lint_antigravity_manifest(report: Report, path: Path) -> None:
    report.files_checked += 1
    try:
        data = json.loads(path.read_text(encoding="utf-8-sig"))
    except json.JSONDecodeError as exc:
        report.add("error", "M001", path, f"invalid JSON: {exc}")
        return
    if not isinstance(data, dict):
        report.add("error", "M001", path, "plugin.json must be a JSON object")
        return
    name = data.get("name")
    if not isinstance(name, str) or not re.fullmatch(r"[a-zA-Z0-9_-]+", name):
        report.add("error", "M001", path, "name is required and must match ^[a-zA-Z0-9-_]+$ (CLI)")
    elif not NAME_RE.match(name):
        report.add("warning", "M004", path, f"name '{name}' is not lowercase kebab-case (required by Marketplace and agy plugin validate --strict)")
    if not isinstance(data.get("description"), str):
        report.add("warning", "M002", path, "description is required by the Antigravity CLI")
    for key in sorted(set(data) - AG_MANIFEST_KEYS, key=str):
        if key in AG_MANIFEST_DEPRECATED_KEYS:
            report.add("warning", "M003", path, f"key '{key}' is deprecated and set only by older plugin imports; remove it")
        else:
            report.add("warning", "M003", path, f"key '{key}' may be rejected (the CLI schema disallows additional properties)")
    if "disabled" in data and not isinstance(data["disabled"], bool):
        report.add("warning", "M004", path, "disabled must be true or false")
    for key in ("suggestedPrompts", "suggested_prompts"):
        if key in data:
            prompts = data[key]
            if not isinstance(prompts, list) or len(prompts) > 3 or not all(isinstance(p, str) and p.strip() for p in prompts):
                report.add("warning", "M004", path, f"{key} must be an array of at most 3 non-empty strings")
    if "logo" in data:
        logo = data["logo"]
        if not isinstance(logo, str) or not logo.strip():
            report.add("warning", "M004", path, "logo must be a non-empty relative asset path or https URL")
        elif not logo.startswith("https://"):
            norm = posixpath.normpath(logo)
            if "\\" in logo or logo.startswith("/") or re.match(r"^[A-Za-z][A-Za-z0-9+.-]*:", logo) or norm.startswith("..") or Path(logo).suffix.lower() not in AG_LOGO_EXTS:
                report.add("warning", "M004", path, "logo must be a relative forward-slash path ending in .png, .svg, .jpg, .jpeg or .webp")
            else:
                plugin_base = path.parent.parent if path.parent.name in (".antigravity-plugin", ".gemini-plugin") else path.parent
                if not (plugin_base / norm).is_file():
                    report.add("warning", "M004", path, f"logo asset not found: {logo}")


def agent_files(agents_dir: Path, platform: str) -> list[Path]:
    if platform == "claude-code":
        return [f for f in walk_files(agents_dir) if f.suffix == ".md"]
    if platform == "antigravity":
        return sorted(list(agents_dir.glob("*.md")) + list(agents_dir.glob("*/agent.md")))
    return sorted(agents_dir.glob("*.md"))


def lint_path(report: Report, path: Path, platform: str) -> None:
    if not path.exists():
        report.add("error", "X001", path, "path does not exist")
        return
    if path.is_dir():
        if (path / "SKILL.md").is_file():
            lint_skill(report, path, platform)
        elif any((path / sub).is_dir() for sub in ("skills", "agents", "rules")):
            lint_container(report, path, platform)
        else:
            report.add("error", "X002", path, "folder is neither a skill nor a root with skills/, agents/ or rules/")
        return
    if path.name == "SKILL.md":
        lint_skill(report, path.parent, platform)
    elif path.name in INSTRUCTION_FILES:
        lint_instructions(report, path, platform)
    elif path.suffix == ".md" and "rules" in path.parent.parts[-1:]:
        lint_rule(report, path, platform)
    elif path.suffix == ".md" and ("agents" in path.parent.parts or path.name == "agent.md"):
        lint_agent(report, path, platform)
    else:
        report.add("error", "X003", path, "cannot tell what this file is (expected SKILL.md, an agent under agents/, a rule under rules/, or an instruction file)")


# --- project mode ----------------------------------------------------------------
def detect_platforms(root: Path) -> list[str]:
    found = []
    if (root / ".claude").is_dir() or (root / "CLAUDE.md").is_file():
        found.append("claude-code")
    if (root / ".agents").is_dir() or (root / ".agent").is_dir() or (root / "GEMINI.md").is_file():
        found.append("antigravity")
    if (root / ".opencode").is_dir() or (root / "opencode.json").is_file():
        found.append("opencode")
    return found or list(PLATFORMS)


def skill_dirs(folder: Path) -> list[Path]:
    return sorted(p for p in folder.iterdir() if p.is_dir() and (p / "SKILL.md").is_file()) if folder.is_dir() else []


def lint_project(report: Report, root: Path, platforms: list[str]) -> None:
    if (root / ".agent").is_dir():
        report.add("warning", "P001", root / ".agent", "legacy Antigravity folder; current root is .agents/")
    for wf in (root / ".agent" / "workflows", root / ".agents" / "workflows"):
        if wf.is_dir():
            report.add("error", "P002", wf, "legacy Antigravity workflows are deprecated; convert them to skills (/migrate-workflows)")
    for name in ("AGENTS.md", "CLAUDE.md", "GEMINI.md"):
        if (root / name).is_file():
            target = "claude-code" if name == "CLAUDE.md" else ("antigravity" if name == "GEMINI.md" else platforms[0])
            lint_instructions(report, root / name, target)

    if "claude-code" in platforms:
        for d in skill_dirs(root / ".claude" / "skills"):
            lint_skill(report, d, "claude-code")
        if (root / ".claude" / "agents").is_dir():
            for f in agent_files(root / ".claude" / "agents", "claude-code"):
                lint_agent(report, f, "claude-code")
        for f in sorted((root / ".claude" / "rules").glob("*.md")) if (root / ".claude" / "rules").is_dir() else []:
            lint_rule(report, f, "claude-code")
    if "antigravity" in platforms:
        for base in (root / ".agents", root / ".agent"):
            if base.is_dir():
                lint_container(report, base, "antigravity")
                plugins = base / "plugins"
                if plugins.is_dir():
                    for p in sorted(x for x in plugins.iterdir() if x.is_dir()):
                        lint_container(report, p, "antigravity")
    if "opencode" in platforms:
        for d in skill_dirs(root / ".opencode" / "skills"):
            lint_skill(report, d, "opencode")
        if (root / ".opencode" / "agents").is_dir():
            for f in agent_files(root / ".opencode" / "agents", "opencode"):
                lint_agent(report, f, "opencode")
        check_opencode_collisions(report, root)


def check_opencode_collisions(report: Report, root: Path) -> None:
    seen: dict[str, Path] = {}
    for folder in (root / ".opencode" / "skills", root / ".claude" / "skills", root / ".agents" / "skills"):
        for d in skill_dirs(folder):
            if d.name in seen:
                first = seen[d.name]
                if d.resolve() == first.resolve():
                    report.add("warning", "P003", d, f"OpenCode reaches skill '{d.name}' through two paths (also {first}); it may load it twice")
                    continue
                hint = " (set OPENCODE_DISABLE_CLAUDE_CODE_SKILLS=1 if the .claude copy is a Claude-only variant)" if ".claude" in (d.parts + first.parts) else ""
                report.add("error", "P003", d, f"OpenCode sees skill '{d.name}' twice (also {first}); names must be unique{hint}")
            else:
                seen[d.name] = d


# --- platform cards --------------------------------------------------------------
CARD_MAX_AGE_DAYS = 90
LAST_VERIFIED = re.compile(r"^Last verified:\s*(\d{4}-\d{2}-\d{2})", re.M)


def lint_cards(report: Report, folder: Path, today: date | None = None) -> None:
    """Platform knowledge goes stale; every card must say when it was last checked."""
    today = today or date.today()
    for path in sorted(folder.glob("*.md")):
        text = path.read_text(encoding="utf-8-sig")
        if not text.startswith("# Platform card:"):
            continue
        report.files_checked += 1
        m = LAST_VERIFIED.search(text)
        try:
            verified = date.fromisoformat(m.group(1)) if m else None
        except ValueError:
            verified = None
        if verified is None:
            report.add("warning", "C001", path, "no 'Last verified: YYYY-MM-DD' line")
        elif (age := (today - verified).days) > CARD_MAX_AGE_DAYS:
            report.add("warning", "C002", path, f"last verified {age} days ago (> {CARD_MAX_AGE_DAYS}); re-check it with the platform-researcher agent")


# --- cli -------------------------------------------------------------------------
def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(prog="lint.py", description=__doc__.split("\n\n")[0])
    parser.add_argument("paths", nargs="*", type=Path)
    parser.add_argument("--platform", action="append", choices=PLATFORMS)
    parser.add_argument("--project", type=Path)
    parser.add_argument("--cards", type=Path)
    parser.add_argument("--json", action="store_true")
    parser.add_argument("--strict", action="store_true")
    args = parser.parse_args(argv)

    report = Report()
    if args.cards:
        if not args.cards.is_dir():
            parser.error(f"--cards {args.cards} is not a directory")
        lint_cards(report, args.cards)
    elif args.project:
        if not args.project.is_dir():
            parser.error(f"--project {args.project} is not a directory")
        lint_project(report, args.project, args.platform or detect_platforms(args.project))
    elif args.paths:
        if not args.platform or len(args.platform) != 1:
            parser.error("give exactly one --platform when checking paths")
        for p in args.paths:
            lint_path(report, p, args.platform[0])
    else:
        parser.error("give PATHs with --platform, --project DIR or --cards DIR")

    errors, warnings, infos = (report.count(lvl) for lvl in LEVELS)
    if args.json:
        print(json.dumps({"files_checked": report.files_checked, "errors": errors, "warnings": warnings,
                          "infos": infos, "findings": [asdict(f) for f in report.findings]}, indent=2))
    else:
        current = None
        for f in sorted(report.findings, key=lambda f: (f.path, LEVELS.index(f.level), f.code)):
            if f.path != current:
                current = f.path
                print(f"\n{f.path}")
            print(f"  {f.level:<7} {f.code}  {f.message}")
        print(f"\n{errors} error(s), {warnings} warning(s), {infos} info - {report.files_checked} file(s) checked")
    return 1 if errors or (args.strict and warnings) else 0


if __name__ == "__main__":
    sys.exit(main())
